#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "md4c-html.h"
static void process_output(const MD_CHAR* text, MD_SIZE size, void* userdata){(void)text;(void)size;(void)userdata;}
int main(int argc,char**argv){if(argc<2)return 2; FILE*f=fopen(argv[1],"rb"); if(!f)return 2; fseek(f,0,SEEK_END); long l=ftell(f); fseek(f,0,SEEK_SET); uint8_t* data=malloc(l?l:1); fread(data,1,l,f); fclose(f); if(l>=8){ unsigned parser_flags=((unsigned*)data)[0]; unsigned renderer_flags=((unsigned*)data)[1]; md_html(data+8,(MD_SIZE)l-8,process_output,NULL,parser_flags,renderer_flags);} free(data); return 0;}
